var on = false, bl = [];
Array.prototype.forEach.call(t.querySelectorAll('h5.tsec, div.crit, div.sp-dx'), function(n){
  if(n.tagName === 'H5') on = n === h; else if(on && !n.parentElement.closest('div.crit, div.sp-dx')) bl.push(n);
});
if(!bl.length) return null;

edits.with:
var on = false, bl = [], fg = [];   // s164: fg, the step's window figures (figure.lcw)
Array.prototype.forEach.call(t.querySelectorAll('h5.tsec, div.crit, div.sp-dx, figure.lcw'), function(n){
  if(n.tagName === 'H5') on = n === h; else if(on && !n.parentElement.closest('div.crit, div.sp-dx, figure.lcw')) (n.tagName === 'FIGURE' ? fg : bl).push(n);
});
if(!bl.length && !fg.length) return null;

/* s164: a window figure one of whose rows names the row's diagnosis (Brief psychotic disorder, Delirium tremens) */
for(var f = 0; f < fg.length; f++){
  var nm = fg[f].querySelectorAll('.wr .nm, .tr .nm');
  for(var j = 0; j < nm.length; j++){
    var x = nm[j].cloneNode(true); x.querySelectorAll('.mask-toggle, button').forEach(function(y){ y.remove(); });   // the Recall toggle's own words
    var nt = pvToks(x.textContent); if(pvIn(core, nt) || pvIn(nt, all)) return fg[f];
  }
}
var tt = pvToks((t.querySelector('h4') || {}).textContent || '');
return pvIn(tt, all) || pvIn(core, tt) ? (bl[0] || fg[0]) : null;

